mapper.select:
SELECT sc.mec_id, sc.campus_id, stu.id, stu.student_name, stu.students_phone, stu.grade, stu.school_name, tea.id teacher_id, tea.name teacher_name, GROUP_CONCAT( cls.class_name ) classes FROM bd_student_class sc LEFT JOIN bd_student stu ON sc.student_id = stu.id LEFT JOIN bd_class cls ON sc.class_id = cls.id LEFT JOIN bd_teacher tea ON cls.bishop_teacher_id = tea.id WHERE class_id IN ( SELECT id FROM bd_class WHERE is_delete = 0 and mec_id = #{mecId} and campus_id = #{campusId} and id != ''
and bishop_teacher_id = #{teacherId}
)
and stu.student_name like CONCAT('%',#{studentName},'%')
and stu.students_phone like CONCAT('%',#{studentsPhone},'%')
and sc.is_delete = 0 GROUP BY stu.id

SELECT id,student_name,students_phone,school_name,grade,age,is_delete,mec_id,campus_id,is_ordinary FROM bd_student WHERE id NOT IN ( SELECT student_id FROM bd_student_class WHERE class_id = #{id} and is_delete = 0 and student_id != '') AND is_ordinary = 0 AND is_delete = 0 AND mec_id = #{mecId} AND campus_id = #{campusId}
and student_name like CONCAT('%',#{studentName},'%')
ORDER BY create_time DESC , id DESC

SELECT sc.student_id id, stu.student_name, GROUP_CONCAT( cls.class_name ) classes FROM bd_student_class sc LEFT JOIN bd_student stu ON sc.student_id = stu.id LEFT JOIN bd_class cls ON sc.class_id = cls.id WHERE cls.is_delete = 0 AND sc.is_delete = 0 AND stu.is_delete = 0 AND sc.mec_id = #{mecId} AND sc.campus_id = #{campusId}
AND cls.bishop_teacher_id = #{teacherId}
AND sc.student_id = #{id}
GROUP BY stu.id

SELECT id,student_name,students_phone,school_name,grade,age,is_delete,mec_id,campus_id,is_ordinary FROM bd_student WHERE id IN
#{id}
AND is_ordinary = 0 AND is_delete = 0

SELECT id,student_name,students_phone,school_name,grade,age,is_delete,mec_id,campus_id,is_ordinary FROM bd_student WHERE id IN
#{id}
AND is_ordinary = 0 AND is_delete = 0 AND mec_id = #{mecId} AND campus_id = #{campusId}

SELECT s.student_name AS studentName, s.students_phone AS studentsPhone, s.parents_name AS parentsName, s.parents_phone AS parentsPhone, GROUP_CONCAT(DISTINCT c.class_name) AS classNames, co.course_name AS courseName, ct.total_number AS totalNumber, ct.remaining_number AS remainingNumber, (SELECT SUM(p.amount_cny) FROM bd_course_purchase p WHERE p.student_id = s.id AND p.course_id = co.id AND p.is_delete = 0) AS amountCnySum FROM bd_student s LEFT JOIN bd_student_class sc ON sc.student_id = s.id AND sc.is_delete = 0 LEFT JOIN bd_class c ON c.id = sc.class_id AND c.is_delete = 0 LEFT JOIN bd_course_time ct ON ct.student_id = s.id AND ct.is_delete = 0 LEFT JOIN bd_course co ON co.id = ct.course_id AND co.is_delete = 0 WHERE s.is_delete = 0 AND s.is_ordinary = 0 AND s.mec_id = #{mecId}
AND s.campus_id = #{campusId}
AND s.student_name LIKE CONCAT('%', #{studentName}, '%')
GROUP BY s.id, co.id, ct.id ORDER BY s.id, co.id
